<template>
  <section class="page upgrade-page" v-loading="loading">
    <header class="page-header"><div><span class="eyebrow">AGENT TASK HARNESS</span><h1>智能体设备任务</h1><p>从证据调查到受控修复，记录计划、审批、工具调用和独立复查。</p></div><div class="header-actions"><el-button @click="load">刷新</el-button><el-button :disabled="!controlSession.token || busy || collectionOnly" @click="recover">检查超时任务</el-button></div></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon role="alert" />
    <DeviceControlToken />
    <section class="operation-section"><h2>创建任务</h2><el-form label-position="top" class="upgrade-form-grid" @submit.prevent="create"><el-form-item label="目标资产" required><el-select v-model="form.asset_id" aria-label="目标资产" @change="form.risk_id = null"><el-option v-for="asset in assets" :key="asset.id" :value="asset.id" :label="asset.hostname" /></el-select></el-form-item><el-form-item label="任务目标"><el-select v-model="form.goal" aria-label="任务目标"><el-option label="纯资产采集（不运行 CVE）" value="collect" /><el-option label="补采与调查" value="investigate" :disabled="collectionOnly" /><el-option label="受控软件包修复" value="repair" :disabled="collectionOnly" /></el-select></el-form-item><el-form-item v-if="form.goal !== 'collect'" label="关联风险事件" :required="form.goal === 'repair'"><el-select v-model="form.risk_id" aria-label="关联风险事件" clearable><el-option v-for="risk in assetRisks" :key="risk.risk_id || risk.id" :value="risk.risk_id || risk.id" :label="risk.cve_id + ' / ' + risk.package_name" /></el-select></el-form-item><el-form-item v-if="form.goal === 'repair' && !isUbuntu" label="已登记修复产物" required><el-select v-model="form.artifact_id" aria-label="已登记修复产物"><el-option v-for="item in artifacts" :key="item.id" :value="item.id" :label="item.id + ' / ' + item.package_name + ' ' + item.version" /></el-select></el-form-item><el-form-item label="生成"><el-button native-type="submit" type="primary" :disabled="!controlSession.token || !form.asset_id || (form.goal === 'repair' && (!form.risk_id || (!isUbuntu && !form.artifact_id)))" :loading="creating">创建计划</el-button></el-form-item></el-form><p v-if="form.goal === 'repair' && !isUbuntu && !artifacts.length" class="operation-help">尚未登记修复产物。请先在后端配置软件包、SHA256、回退产物及漏洞回归和业务检查脚本。</p><p class="operation-help">创建计划不会执行设备修改。修复需审批具体计划；执行中断后先复查，不自动重放写操作。</p></section>
    <section class="operation-section"><div class="section-head"><h2>任务记录</h2><span>{{ runs.length }} 条</span></div><DataTable :rows="runs" max-height="340"><el-table-column label="任务" min-width="165"><template #default="{ row }"><button class="table-link mono" @click="select(row.id)">{{ row.id.slice(0, 12) }}</button></template></el-table-column><el-table-column label="资产" min-width="160"><template #default="{ row }">{{ assetName(row.asset_id) }}</template></el-table-column><el-table-column label="目标" min-width="130"><template #default="{ row }">{{ goalLabel(row.plan.goal) }}</template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{ row }"><el-tag :type="row.status === 'verified' ? 'success' : ['failed', 'blocked'].includes(row.status) ? 'danger' : 'info'">{{ stateLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="当前步骤" min-width="180"><template #default="{ row }">{{ toolLabel(row.current_step) }}</template></el-table-column><el-table-column label="操作" width="110"><template #default="{ row }"><el-button text @click="select(row.id)">查看记录</el-button></template></el-table-column></DataTable><el-empty v-if="!runs.length" description="选择资产创建第一项证据调查任务" /></section>
    <section v-if="selected" class="operation-section" aria-label="任务详情">
      <div class="section-head"><div><h2>{{ assetName(selected.asset_id) }} · {{ stateLabel(selected.status) }}</h2><p class="mono">{{ selected.id }}</p></div><el-tag>{{ selected.current_step ? toolLabel(selected.current_step) : '计划已生成' }}</el-tag></div>
      <el-alert v-if="selected.error" :title="selected.error" type="error" :closable="false" />
      <el-alert v-if="selected.plan.blocked_reasons?.length" :title="selected.plan.blocked_reasons.join('；')" type="warning" :closable="false" />
      <UbuntuRepairEvidence :run="selected" /><ol class="task-plan"><li v-for="(step, index) in selected.plan.steps" :key="index">{{ toolLabel(step) }}</li></ol>
      <dl class="description-grid"><div><dt>批准人记录</dt><dd>{{ selected.approved_by || '尚未审批 / 无需写审批' }}</dd></div><div><dt>已尝试次数</dt><dd>{{ selected.attempts }}</dd></div><div class="wide"><dt>计划摘要</dt><dd class="mono wrap-anywhere">{{ selected.plan_hash }}</dd></div><div v-if="selected.plan.artifact" class="wide"><dt>修复产物</dt><dd>{{ selected.plan.artifact.package_name }} → {{ selected.plan.artifact.version }} · {{ selected.plan.artifact.board_name }}</dd></div></dl>
      <div class="upgrade-actions"><el-button v-if="selected.plan.adapter === 'ubuntu-apt-v1' && ['awaiting_preflight','preflight_failed'].includes(selected.status)" :disabled="!controlSession.token || busy" @click="act('dry-run')">只读修复预演</el-button><el-button v-if="selected.status === 'awaiting_approval'" :disabled="!controlSession.token || busy" @click="openApproval('approve')">审批此计划</el-button><el-button v-if="canExecute" type="primary" :disabled="!controlSession.token || busy" :loading="busy" @click="act('execute')">{{ selected.plan.goal === 'collect' ? '执行采集' : selected.plan.goal === 'repair' ? '执行已审批修复' : '执行调查' }}</el-button><el-button v-if="['verification_required','interrupted'].includes(selected.status) && selected.plan.goal === 'repair'" :disabled="!controlSession.token || busy" @click="act('verify')">重新复查设备</el-button><el-button v-if="selected.plan.goal === 'repair' && !selected.plan.adapter && ['verification_required','interrupted','verified'].includes(selected.status)" type="warning" plain :disabled="!controlSession.token || busy" @click="openApproval('rollback')">审批并回退</el-button><el-button v-if="['pending','awaiting_approval','approved','blocked','needs_evidence','failed'].includes(selected.status)" :disabled="!controlSession.token || busy" @click="act('cancel')">取消任务</el-button></div>
      <p v-if="busy || selected.status === 'running'" class="operation-help" aria-live="polite">任务执行中，正在刷新审计记录。网络请求中断时，请先刷新确认任务状态。</p>
      <h3>工具调用审计</h3><el-timeline><el-timeline-item v-for="call in selected.tool_calls || []" :key="call.id" :timestamp="formatTime(call.created_at)" placement="top"><strong>{{ toolLabel(call.tool) }}</strong> · {{ stateLabel(call.status) }} · {{ call.duration_ms }} ms <el-tag v-if="call.side_effect" size="small" type="warning">设备写操作</el-tag><p v-if="call.error" class="operation-error">{{ call.error }}</p><el-collapse><el-collapse-item title="查看调用参数和结果"><pre class="upgrade-json">{{ JSON.stringify({ arguments: call.arguments, output: call.output }, null, 2) }}</pre></el-collapse-item></el-collapse></el-timeline-item></el-timeline><el-empty v-if="!selected.tool_calls?.length" description="计划尚未执行，没有工具调用记录" />
      <h3>结果与待补证据</h3><pre class="upgrade-json">{{ JSON.stringify(selected.result, null, 2) }}</pre>
    </section>
    <el-dialog v-model="approvalDialog" :title="approvalAction === 'rollback' ? '审批回退计划' : '审批修复计划'" width="min(540px, 94vw)"><p>{{ approvalAction === 'rollback' ? '使用计划中预先登记的旧版本产物回退。回退恢复业务不代表漏洞已修复。' : '审批仅适用于当前资产、版本、连接和产物。任一关键事实变化后须重新制定计划。' }}</p><el-form label-position="top" @submit.prevent="submitApproval"><el-form-item label="操作人署名" required><el-input aria-label="操作人署名" v-model="approval.actor" /></el-form-item><el-form-item label="审批理由" required><el-input aria-label="审批理由" v-model="approval.reason" type="textarea" /></el-form-item><el-alert v-if="approvalError" :title="approvalError" type="error" :closable="false" /><div class="upgrade-actions"><el-button @click="approvalDialog = false">取消</el-button><el-button native-type="submit" type="primary" :disabled="!approval.actor.trim() || approval.reason.trim().length < 3" :loading="busy">确认审批</el-button></div></el-form></el-dialog>
  </section>
</template>
<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from "vue";
import { useRoute } from "vue-router";
import { ElMessage } from "element-plus";
import UbuntuRepairEvidence from "../components/UbuntuRepairEvidence.vue";
import DataTable from "../components/DataTable.vue";
import DeviceControlToken from "../components/DeviceControlToken.vue";
import { fetchAssets, fetchRiskRanking } from "../api";
import { controlSession, errorMessage, fetchHarnessRuns, fetchHarnessRun, fetchRepairArtifacts, createHarnessRun, actOnHarnessRun, recoverHarnessRuns, fetchDeviceCapabilities } from "../api/deviceOperations";
const route = useRoute(); const loading = ref(false); const busy = ref(false); const creating = ref(false); const error = ref(""); const assets = ref([]); const risks = ref([]); const artifacts = ref([]); const runs = ref([]); const selected = ref(null);
const form = reactive({ asset_id: Number(route.query.asset) || null, risk_id: Number(route.query.risk) || null, goal: "investigate", artifact_id: "", model_review: false });
const collectionOnly = ref(false);
const goalLabel = value => ({ collect: '纯资产采集', investigate: '证据调查', repair: '受控修复' }[value] || '未记录');
const approvalDialog = ref(false); const approvalAction = ref("approve"); const approval = reactive({ actor: "", reason: "" }); const approvalError = ref(""); let timer; let polling = false;
const isUbuntu = computed(() => assets.value.find(a => a.id === form.asset_id)?.distribution === "ubuntu");
const assetRisks = computed(() => risks.value.filter(r => r.asset_id === form.asset_id));
const canExecute = computed(() => selected.value && (selected.value.plan.goal === "collect" ? selected.value.status === "pending" : selected.value.plan.goal === "repair" ? selected.value.status === "approved" : ["pending", "needs_evidence", "failed"].includes(selected.value.status)));
const assetName = id => assets.value.find(a => a.id === id)?.hostname || "资产 " + id;
const stateLabel = value => ({ awaiting_preflight: "待只读预演", preflight_failed: "预演未通过", queued_remote: "已排队到节点", pending: "待执行", blocked: "前置条件未满足", awaiting_approval: "待审批", approved: "已审批", running: "执行中", completed: "已完成", needs_evidence: "需要补充证据", verified: "修复验证通过", verification_required: "需要复查设备", failed: "失败", interrupted: "中断待检查", cancelled: "已取消", rolled_back: "已回退，漏洞未消除" }[value] || value);
const toolLabel = value => ({ ubuntu_dry_run: "Ubuntu 只读修复预演", ubuntu_dry_run_dispatch: "将只读预演交给认证节点", ubuntu_dry_run_result: "记录真实包版本和依赖预演", approve_exact_plan: "独立审批精确计划", ubuntu_preflight: "执行前重新核验目标与软件包", ubuntu_install_pinned_packages: "维护已批准的白名单包", official_rematch: "按新采集和官方公告重新匹配", risk_update_recommendation: "生成风险状态更新建议", collect_inventory: "采集设备清单", inspect_inventory: "检查已有清单", inspect_runtime: "检查运行时覆盖", inspect_evidence: "构建证据包", expert_review: "专家智能体复核", validate_plan: "校验计划适用性", install_registered_package: "安装已登记修复包", verify_vendor_version: "复核厂商版本依据", regression_check: "漏洞回归检查", business_check: "业务检查", install_rollback_package: "安装已登记回退包" }[value] || value || "—");
const formatTime = value => value ? new Date(value).toLocaleString("zh-CN") : "—";
async function load() { loading.value = true; error.value = ""; try { const capabilities = await fetchDeviceCapabilities(); collectionOnly.value = Boolean(capabilities.collection_only); if (collectionOnly.value) { form.goal = 'collect'; if (!controlSession.token) return; } [assets.value, risks.value, artifacts.value, runs.value] = await Promise.all([fetchAssets(), collectionOnly.value ? Promise.resolve([]) : fetchRiskRanking(), collectionOnly.value ? Promise.resolve([]) : fetchRepairArtifacts(), fetchHarnessRuns()]); if (selected.value || route.query.run) selected.value = await fetchHarnessRun(selected.value?.id || route.query.run); } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function select(id) { try { selected.value = await fetchHarnessRun(id); } catch (e) { error.value = errorMessage(e); } }
async function create() { creating.value = true; error.value = ""; try { selected.value = await createHarnessRun({ ...form, risk_id: form.goal === 'collect' ? null : form.risk_id || null, artifact_id: form.goal === 'collect' ? '' : form.artifact_id, model_review: false }); runs.value = await fetchHarnessRuns(); ElMessage.success("任务计划已创建"); } catch (e) { error.value = errorMessage(e); } finally { creating.value = false; } }
async function act(action, payload = null) { if (!selected.value) return false; busy.value = true; error.value = ""; try { selected.value = await actOnHarnessRun(selected.value.id, action, payload); runs.value = await fetchHarnessRuns(); return true; } catch (e) { error.value = errorMessage(e); approvalError.value = error.value; await select(selected.value.id); return false; } finally { busy.value = false; } }
function openApproval(action) { approvalAction.value = action; approval.reason = ""; approvalError.value = ""; approvalDialog.value = true; }
async function submitApproval() { if (await act(approvalAction.value, { plan_hash: selected.value.plan_hash, actor: approval.actor.trim(), reason: approval.reason.trim() })) approvalDialog.value = false; }
async function recover() { try { const result = await recoverHarnessRuns(); ElMessage.info("已标记 " + result.recovered + " 项超时任务，后续先复查设备"); await load(); } catch (e) { error.value = errorMessage(e); } }
onMounted(() => { load(); timer = setInterval(async () => { if (!polling && selected.value && (busy.value || ['running','queued_remote'].includes(selected.value.status))) { polling = true; const id = selected.value.id; try { const result = await fetchHarnessRun(id); if (selected.value?.id === id) selected.value = result; } catch { /* Active operations surface connection errors. */ } finally { polling = false; } } }, 3000); });
onUnmounted(() => clearInterval(timer));
watch(() => controlSession.token, load);
</script>
